theorem.raw:
Let $(\psi_1,\psi_2)$ be an admissible pair in $L^2(\mathbb{R}^n)$. For $f\in L^2(\mathbb{R}^n)$ and $A_2 > A_1 > 0,$ define
\begin{align*}
f_{A_1A_2}(x)= C_{\psi_1\psi_2}^{-1}\int_{A_1}^{A_2}\int_{S0(n)}\int_{\mathbb{R}^n} \langle f, \pi(a,r_{\theta},t)\psi_1\rangle\ \pi(a,r_{\theta},t)\psi_2(x)\ \frac{dtd\theta da}{a^{n+1}}.
\end{align*}
Then, $f_{A_1A_2} \in L^2(\mathbb{R}^n)$ and
\begin{align*}
\widehat{{f_{A_1A_2}}}(\omega) = C_{\psi_1\psi_2}^{-1}\widehat{f}(\omega)\int_{A_1}^{A_2}\int_{S0(n)} \widehat{\psi_{1}}(ar_\theta^{-1}(\omega))\ \widehat{\psi_2}(ar_\theta^{-1}(\omega))\ \frac{d\theta da}{a}.
\end{align*}

Let $(\psi_1,\psi_2)$ be an admissible pair in $L^2(\mathbb{R}^n)$ and  $f\in L^2(\mathbb{R}^n)$ with $\widehat{f} \in L^1(\mathbb{R}^n)$. Then for any $\epsilon,p > 0$, there exist $A_2 > A_1 > 0 $ such that for any $(a,r_{\theta},t) \in G$ with $0< p\leq a$ and $0 < A_1^{'}\leq A_1$, $A_2^{'} \geq A_2,$  the following holds
\begin{align*}
&\left\|\pi(a,r_{\theta},t)f(x)-\left(C_{\psi_1\psi_2}^{-1}\int_{A_1^{'}a}^{A_2^{'}a}\int_{S0(n)}\int_{\mathbb{R}^n}\langle \pi(a,r_{\theta},t)f,\pi(a_1,{r_{\theta}}_1,t_1)\psi_1\rangle\right.\right.\\
&\qquad\qquad \qquad \qquad \qquad \qquad \left.\left.\times \pi(a_1,{r_{\theta}}_1,t_1)\psi_2(x)\ \frac{dt_1d\theta_1da_1}{a_1^{n+1}} \right)\right\|_{\infty}\leq \epsilon.
\end{align*}

Let $G = B\ltimes_{\tau} A$ be an abstract wavelet  group and $\psi \in L^2(A)$ be a feasible wavelet. Let $M\subset G$ be such that $\mu(M)\leq \frac{\sqrt{C_{\psi}}}{\|\psi\|}.$
Then for any $f \in L^2(A)$,
\begin{align*}
\| W_{\psi}f - \chi_{M}W_{\psi}f\|\geq \sqrt{C_{\psi}}\left(1 - \frac{\|\psi\|\ {\mu(M)}^{1/2}}{\sqrt{C_{\psi}}}\right)\|f\|.
\end{align*}

Let $G = B \ltimes_{\tau}(L\times \mathbb{R})$ be a wavelet group, where $L$ is a compact group and $\psi$ be a feasible wavelet. Then for any $f\in L^2(\mathbb{R})$, we have 
\begin{align*}
&\left(\int_{B}\int_{L}\int_{\mathbb{R}}|t|^2|W_{\psi}f(b,l,t)|^2\delta_{\tau}(b) dt\ dl\ db \right)^{1/2}
 \left( \int_{\widehat{L}}\int_{\widehat{R}}|\gamma|^2\|(\delta,\gamma)f\|^2_{\text{HS}}\ d\delta\ d\gamma\right)^{1/2}\\
&\geq\frac{\sqrt{C_{\psi}}}{2}||f||^2.
\end{align*}

lemma.raw:
\label{conn}
Let $G_0$, the identity component of $G$ be non-compact and  $M_{0}\subseteq M \subset G/H$ be such that $ 0 <\mu_{G/H}(M_0)\leq \mu_{G/H}(M) < \infty.$ Then for $\epsilon > 0$ there exists $a \in G_0$ satisfying
\begin{align*}
\mu_{G/H}(M) < \mu_{G/H}(M\cup aM_{0}) < \mu_{G/H}(M)+\epsilon.
\end{align*}

\label{isom}
Let $\psi$ be a feasible wavelet and $f,g\in L^2(A)$. Then 
$\langle W_{\psi}f,W_{\psi}g\rangle = C_{\psi}\langle f,g \rangle$.

proof.raw:
Let $K$ be an arbitrary compact subset of $G/H$ and $K^{'}$ be a compact subset of $G/H$ such that $K\subseteq K^{'}$. Then for $\eta \in \mathcal{H}_{\pi}$ and $sH \in G/H,$ we have
\begin{align*}
&\left\|\pi(sH)\eta - C_{\xi_1\xi_2}^{-1}\int_{s\cdot K^{'}}\left(\frac{\rho(e)}{\rho(a)}\right)\langle \pi(sH)\eta, \pi(aH)\xi_1 \rangle\ \pi(aH)\xi_2\  d\mu_{G/H}(aH)\right\|^2\\
&=\sup\limits_{\|\zeta\|=1}\left|\left(\left\langle  \pi(sH)\eta - C_{\xi_1\xi_2}^{-1}\int_{s\cdot K^{'}}\left(\frac{\rho(e)}{\rho(a)}\right)\langle \pi(s)\eta,
\pi(aH)\xi_1 \rangle\right.\right. \right.\\
&\qquad\qquad \qquad \qquad \left.\times \pi(aH)\xi_2\ d\mu_{G/H}(aH)\right) , \left.\zeta\rangle  \right|^2\\
&=\sup\limits_{\|\zeta\|=1}\left|  C_{\xi_1\xi_2}^{-1} \int_{aH \notin s\cdot K^{'}}\left(\frac{\rho(e)}{\rho(a)}\right)\langle \pi(sH)\eta, \pi(aH)\xi_1 \rangle\right. \\
&\qquad \qquad \qquad \qquad \times \left. \left\langle\pi(aH)\xi_2,\zeta \right\rangle d\mu_{G/H}(aH) \right|^{2}\\
&\leq C_{\xi_1\xi_2}^{-2}\int_{aH \notin s\cdot K^{'}}\left(\frac{\rho(e)}{\rho(a)}\right)\big|\langle \pi(sH)\eta, \pi(aH)\xi_1 \rangle\big|^{2}\ d\mu_{G/H}(aH)\\
&\qquad \qquad \qquad \qquad\times \sup\limits_{\|\zeta\| = 1}\int_{G/H}\left(\frac{\rho(e)}{\rho(a)}\right)\big|\langle\pi(aH)\xi_2,\zeta \rangle\big|^2\ d\mu_{G/H}(aH)\\
&\leq C_{\xi_1\xi_2}^{-2}C_{\xi_2}\int_{aH \notin s\cdot K}\left(\frac{\rho(e)}{\rho(a)}\right)\big|\langle \pi(sH)\eta, \pi(aH)\xi_1 \rangle\big|^{2}\ d\mu_{G/H}(aH)\\
&\leq C_{\xi_1\xi_2}^{-2}C_{\xi_2}\int_{aH \notin  K}\left(\frac{\rho(e)}{\rho(sa)}\right)\big|\langle \eta, \pi(aH)\xi_1 \rangle\big|^{2}\ d\mu_{G/H}(saH)\\
&= C_{\xi_1\xi_2}^{-2}C_{\xi_2}\int_{aH \notin K}\left(\frac{\rho(e)}{\rho(a)}\right)\big|\langle \eta, \pi(aH)\xi_1 \rangle\big|^{2}\ d\mu_{G/H}(aH).
\end{align*}
But, $G/H$ is $\sigma$-compact, therefore, there exists a sequence  $\{K_n\}_{n\in \mathbb{N}}$ of compact subsets of $G/H$ such that $K_n\subset K_{n+1}$  for all $n\in \mathbb{N}$ and   $G/H = \bigcup\limits_{n=1}^{\infty}K_n$. Since $\left|\chi_{K_n}W_{\xi_1}\eta - W_{\xi_1}\eta\right|^2  \to 0 $, as $n\to \infty$ and $\left|\chi_{K_n}W_{\xi_1}\eta - W_{\xi_1}\eta\right|^2 \leq 4|W_{\xi_1}\eta|^2$,
therefore by Lebesgue dominated convergence theorem, it follows that
\begin{flalign*}
&\int_{G/H} \left|\chi_{K_n}W_{\xi_1}\eta(aH) - W_{\xi_1}\eta(aH)\right|^2\ d\mu_{G/H}(aH)\to 0, \ \text{ as } n\to \infty. & 
\end{flalign*}
 Thus, there exists a $K_n$ such that 
\begin{flalign*}
&\int_{G/H} \left|\chi_{K_n}W_{\xi_1}\eta(aH) - W_{\xi_1}\eta(aH)\right|^2 d\mu_{G/H}(aH)\leq \frac{\epsilon}{ C_{\xi_1\xi_2}^{-2}C_{\xi_1}},&
\end{flalign*}
or, equivalently,
\begin{flalign*}
&\int_{aH\notin K_n} \left(\frac{\rho(e)}{\rho(a)}\right)|\langle \eta, \pi(aH)\xi_1 \rangle|^{2}\ d\mu_{G/H}(aH)\leq \frac{\epsilon}{ C_{\xi_1\xi_2}^{-2}C_{\xi_1}}.&
\end{flalign*} 
Therefore, we can choose  a compact subset  $K$ of $G/H$ such that
\begin{align*} \left\|\pi(sH)\eta - C_{\xi_1\xi_2}^{-1}\int_{s\cdot K^{'}}\left(\frac{\rho(e)}{\rho(a)}\right)\langle \pi(sH)\eta, \pi(aH)\xi_1 \rangle \pi(aH)\xi_2\ d\mu_{G/H}(aH)\right\|\leq \epsilon\end{align*}
 for every compact subset $K^{'}$ of $G/H$ containing $K$ and every $s\in G.$

For arbitrary $0 < A_1^{'}< A_{2}^{'}$ and $(a,r_{\theta},t)\in G$ with $p\leq a$, define
\begin{flalign*}
&f_{A_1^{'}a}(x)=C_{\psi_1\psi_2}^{-1} \int_{0}^{A_1^{'}a}\int_{S0(n)}\int_{\mathbb{R}^n}\langle \pi(a,r_{\theta},t)f,\pi(a_1,{r_{\theta_1}},t_1)\psi_1\rangle &\\
&  \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times \pi(a_1,{r_{\theta}}_1,t_1)\psi_2(x)\ \frac{dt_1d\theta_1da_1}{a_1^{n+1}}
\end{flalign*}
and
 \begin{flalign*}
&f_{A_2^{'}a}(x)=C_{\psi_1\psi_2}^{-1} \int_{A_2^{'}a}^{\infty}\int_{S0(n)}\int_{\mathbb{R}^n}\langle \pi(a,r_{\theta},t)f,\pi(a_1,{r_{\theta_1}},t_1)\psi_1\rangle &\\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \times\pi(a_1,{r_{\theta}}_1,t_1)\psi_2(x)\ \frac{dt_1d\theta_1da_1}{a_1^{n+1}}.
\end{flalign*}
Then,
\begin{align*}
&\left\|\pi(a,r_{\theta},t)f(x)-\left(C_{\psi_1\psi_2}^{-1}\int_{A_1^{'}a}^{A_2^{'}a}\int_{S0(n)}\int_{\mathbb{R}^n}\left(\langle \pi(a,r_{\theta},t)f,\pi(a_1,{r_{\theta}}_1,t_1)\psi_1\rangle\right)\right.\right.\\
&\qquad \qquad \qquad \qquad  \qquad \left.\left.\times\  \left(\pi(a_1,{r_{\theta}}_1,t_1)\psi_2(x)\right)\ \frac{dt_1d\theta_1da_1}{a_1^{n+1}}\right) \right\|_{\infty}\\
& = \Big\| f_{A_1^{'}a}(x)+ f_{A_2^{'}a}(x)  \|_{\infty} \leq  \|\widehat{f_{A_1^{'}a}}\|_{1} +  \|\widehat{f_{A_2^{'}a}}\Big\|_{1}\\
&\leq|C_{\psi_1\psi_2}^{-1}|
\int_{\mathbb{R}^n}\left|\widehat{\pi(a,r_{\theta},t)f}(\omega)\right|\int_{S0(n)}\int_{0}^{A_1^{'}a} |\widehat{\psi_{1}}(a_1 {r_{\theta}}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))| \ \frac{da_1d\theta_1}{a_1}d\omega \\
&\qquad+ |C_{\psi_1\psi_2}^{-1}|\int_{\mathbb{R}^n}\left|\widehat{\pi(a,r_{\theta},t)f}(\omega)\right|\int_{S0(n)}\int_{A_2^{'}a}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega. \\
 &\leq |C_{\psi_1\psi_2}^{-1}|\int_{\mathbb{R}^n}|a|^{n/2}|\widehat{f}(ar_{\theta}^{-1}\omega)|\int_{S0(n)}\int_{0}^{A_1^{'}a} |\widehat{\psi_{1}}(a_1 {r_{\theta}}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega \\
&\qquad+ |C_{\psi_1\psi_2}^{-1}|\int_{\mathbb{R}^n}|a|^{n/2}|\widehat{f}(ar_{\theta}^{-1}\omega)|\int_{S0(n)}\int_{A_2^{'}a}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega\\
&\leq |C_{\psi_1\psi_2}^{-1}|\int_{\mathbb{R}^n}|p|^{-n/2}|\widehat{f}(\omega)|\int_{S0(n)}\int_{0}^{A_1^{'}} |\widehat{\psi_{1}}(a_1 {r_{\theta}}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega \\
&\qquad+ |C_{\psi_1\psi_2}^{-1}|\int_{\mathbb{R}^n}|p|^{-n/2}|\widehat{f}(\omega)|\int_{S0(n)}\int_{A_2^{'}}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega.  
\end{align*}
Since both $\psi_1$ and $\psi_2$ are admissible, therefore we get
\begin{align}\label{eq4}
\int_{S0(n)}\int_{0}^{A_1^{'}} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1}\leq C_{\psi_1}C_{\psi_2}< \infty
\end{align}
 and
\begin{align}\label{eq2}
\int_{S0(n)}\int_{A_2^{'}}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1}\leq C_{\psi_1}C_{\psi_2}< \infty.
\end{align}
Also,
\begin{align*}
\lim\limits_{A_1^{'}\to 0}\int_{S0(n)}\int_{0}^{A_1^{'}}|\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1}  =0
\end{align*}
and
\begin{align*}
&\lim\limits_{A_2^{'}\to \infty}\  \int_{S0(n)}\int_{0}^{A_2^{'}} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1} & \\
 &\qquad \qquad =\int_{S0(n)}\int_{0}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1}.
\end{align*}
Thus,
\begin{align*}
\lim\limits_{A_2^{'}\to \infty} \int_{S0(n)}\int_{A_2^{'}}^{\infty}|\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1{r_\theta}_1^{-1}(\omega))|\frac{da_1d\theta_1}{a_1}= 0
\end{align*}
By Lebesgue dominated convergence theorem, we get
\begin{align*}
\lim\limits_{A_1^{'} \to 0} \int_{\mathbb{R}^n}|\widehat{f}(\omega)|\int_{S0(n)}\int_{0}^{A_1^{'}} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega = 0. 
\end{align*}
and
\begin{align*}
\lim\limits_{A_2^{'} \to \infty} \int_{\mathbb{R}^n}|\widehat{f}(\omega)|\int_{S0(n)}\int_{A_2^{'}}^{\infty} |\widehat{\psi_{1}}(a_1{r_\theta}_1^{-1}(\omega))\ \widehat{\psi_2}(a_1 {r_{\theta}}_1^{-1}(\omega))|\ \frac{da_1d\theta_1}{a_1}d\omega = 0. 
\end{align*}
Therefore, we can choose  $0 < A_1\leq A_2$ such that for any $(a,r_{\theta},t)$ with $0< p\leq a$ and  $0< A_1^{'}\leq A_1, A_2<A_2^{'}$, the conclusion of the theorem holds.

Let $P_R :L^2(G) \to L^2(G) $ be the orthogonal projection from $L^2(G)$ to the closed subspace $W_{\psi}(L^2(A))$ and $P_M :L^2(G) \to L^2(G)$ be the orthogonal projection from $L^2(G)$ to the closed subspace of functions with support contained in $M.$ Now, 
\begin{align}\label{conc}
\| W_{\psi}f - \chi_{M}\cdot W_{\psi}f\| &= \| W_{\psi}f- P_MP_R(W_{\psi}f)\| \nonumber \\ \nonumber
& \geq \|W_{\psi}f\| - \|P_MP_R\|\ \|W_{\psi}f\|\\
&= (1-\|P_MP_R\|)\ \sqrt{C_{\psi}}\ \|f\|.
\end{align}  
Now $P_R$ being a projection on a reproducing kernel Hilbert space can be represented by
\begin{align*}
P_RF(b,a) = \langle F(b^{'},a^{'}), k((b^{'},a^{'}), (b,a)) \rangle, 
\end{align*}
where $F \in L^2(G)$ and $k(.,.)$ is the reproducing kernel. Thus, for every $F\in L^2(G),$ we have
\begin{align*}
P_MP_RF(b,a) = 
\int_{G} \chi_{M}(b,a)k((b^{'},a^{'}), (b,a))F(b^{'},a^{'})d\mu(b^{'},a^{'}).
\end{align*} 
 From \cite{hal;78}, the operator norm $\|P_MP_R\|$  is given by
\begin{flalign*}
\| P_MP_R\|^{2} &= \int_{G}\int_{G}|\chi_{M}(b,a)\ k((b^{'},a^{'}),(b,a))|^2\ d\mu(b,a)\ d\mu(b^{'},a^{'})&\\
&=\int_{G}\int_{G}|\chi_{M}(b,a)\frac{1}{C_{\psi}}\langle \psi_{ba}, \psi_{b^{'}a^{'}}\rangle |^2\ d\mu(b,a)\ d\mu(b^{'},a^{'})&\\
&=\frac{1}{C_{\psi}^2}\int_{M} \int_{G}|W_{\psi}\psi_{ba}(b^{'},a^{'})|^2\ d\mu(b^{'},a^{'})\ d\mu(b,a)&\\
&=\frac{1}{C_{\psi}}\int_{M}\|\psi_{ba}\|^2\ d\mu(b,a)&\\
&= \frac{1}{C_{\psi}}\|\psi\|^{2}\ \mu(M).
\end{flalign*}
On substituting the value $\|P_MP_R\|$ into (\ref{conc}), we get the desired inequality.

For almost all $b\in B$, using Heisenberg inequality for Fourier transform on $L\times \mathbb{R}$ (see \cite{bans;15}), we have
\begin{align*}
&\Big(\int_{L}\int_{\mathbb{R}}|t|^2|W_{\psi}f(b,l,t)|^2dl\  dt\Big)^{1/2}\Big(\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta, \gamma)W_{\psi}f(b,\cdot,\cdot)\|_{\text{HS}}^2\ d\delta\ d\gamma \Big)^{1/2}\\
& \geq \frac{1}{2}\int_{L}\int_{\mathbb{R}}|W_{\psi}f(b,l,t)|^2dl\ dt
\end{align*}
On integrating both sides with respect to the measure $\delta_{\tau}(b)db$, we get
\begin{align*}
&\int_B\Big(\int_{L}\int_{\mathbb{R}}|t|^2|W_{\psi}f(b,l,t)|^2 dl\ dt\Big)^{1/2}\Big(\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta, \gamma)W_{\psi}f(b,\cdot,\cdot)\|_{\text{HS}}^2 \ d\delta\ d\gamma \Big)^{1/2} \delta_{\tau}(b)db \\
&\geq  \frac{1}{2}\int_{B}\int_{L}\int_{\mathbb{R}}|W_{\psi}f(b,l,t)|^2 \delta_{\tau}(b) dl\ dt\ db.
\end{align*}
Using Lemma \ref{isom} and  Cauchy-Schwarz inequality, it follows that
\begin{flalign}\label{cauc}
&\left(\int_B\int_{L}\int_{\mathbb{R}}|t|^2|W_{\psi}f(b,l,t)|^2 \delta_{\tau}(b) dl\ dt\ db\right)^{1/2}\nonumber &\\
& \times \left(\int_B\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta, \gamma)W_{\psi}f(b,\cdot,\cdot)\|_{\text{HS}}^2\ \delta_{\tau}(b) d\delta\ d\gamma\ db \right)^{1/2} \geq\frac{1}{2}C_{\psi}\|f\|^2.
 \end{flalign}
 Since, \begin{align*}
 \|(\delta,\gamma)W_{\psi}f(b,.,.)\|_{\text{HS}}^2 & = \text{tr}((\delta,\gamma)W_{\psi}f(b,.,.)(\delta,\gamma)W_{\psi}f(b,.,.)^*)\\
 &= \delta_{\tau}(b)\text{tr}((\delta,\gamma)f^*(\delta,\gamma)f(\delta,\gamma)(\psi \circ \tau_{b^{-1}})^*(\delta,\gamma)(\psi \circ \tau_{b^{-1}})),
 \end{align*}
 therefore, on using feasibility condition, we obtain
 \begin{align}\label{adm}
& \int_B\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta, \gamma)W_{\psi}f(b,\cdot,\cdot)\|_{\text{HS}}^2\  \delta_{\tau}(b) d\delta\ d\gamma\ db\nonumber\\
& = \int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\int_B \text{tr}((\delta,\gamma)f^*(\delta,\gamma)f(\delta,\gamma)(\psi \circ \tau_{b^{-1}})^*(\delta,\gamma)(\psi \circ \tau_{b^{-1}}))\delta_{\tau}(b)^2 db\ d\delta\ d\gamma\nonumber \\
 &=\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2C_{\psi}\text{tr}((\delta,\gamma)f^*(\delta,\gamma)f(\delta,\gamma))d\delta\ d\gamma \nonumber \\
 &= C_{\psi}\int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta,\gamma)f\|_{\text{HS}}^2\ d\delta\ d\gamma.
 \end{align}
 On substituting (\ref{adm}) into (\ref{cauc}), we get 
 \begin{align*}
 &\left(\int_B\int_{L}\int_{\mathbb{R}}|t|^2|W_{\psi}f(b,l,t)|^2 \delta_{\tau}(b) dl\ dt\ db\right)^{1/2}
\left( \int_{\widehat{L}}\int_{\mathbb{R}}|\gamma|^2\|(\delta,\gamma)f\|_{\text{HS}}^2\ d\delta\ d\gamma\right)^{1/2} &\\
& \geq\frac{1}{2}\sqrt{C_{\psi}}\ \|f\|^2. &\qedhere 
\end{align*}

remark.raw:
\noindent
\begin{enumerate}
 \item If we drop the irreducibility of $\pi$, then the conclusion of  Theorem \ref{concth} may not hold.
 Consider a locally compact  abelian topological group $G$ and the left regular representation $\pi$ of $G$. Then every non-zero function  $\psi \in C_{00}(G)$ is an admissible wavelet. Fix non-zero functions $f,\psi \in C_{00}(G).$
 Then, $W_{\psi}f(x)=\langle f, \pi(x)\psi \rangle = f* \psi^{\star}(x)$, where $*$ is the convolution and $\psi^{\star}(x)= \overline{\psi(-x)}$.  Hence $W_{\psi}f \in C_{00}(G).$

 \item If G is an abelian locally compact group and $\pi$ is an irreducible representation of $G$, then the support of wavelet transform is $G.$ In this case $W_{\xi}\eta(x) =  \overline{ \chi(x)}\langle \eta, \xi\rangle$, where $\chi$ is the character of $G$ associated with $\pi.$ 
This may not be true if we consider a non-abelian compact group G.
 Consider $G = \mathbb{T}\times D_3, \text{ where } D_{3} = \{x,y : x^3 = e = y^2, xy = yx^{-1} \}.$
 Let $\pi$ be an irreducible unitary representation of G given by:
 \begin{align*}
 \pi(t,x) = e^{int} \otimes \begin{bmatrix}
 \omega & 0\\
 0 & \omega^{-1}
 \end{bmatrix},\ 
 \pi(t,y) = e^{int} \otimes \begin{bmatrix}
 0 & 1\\
 1 & 0
 \end{bmatrix}, 
 \end{align*}
  where $\omega^{3} = 1$,  $ n\in \mathbb{Z}$ is fixed and $\otimes $ being the outer tensor product.
 If we consider $\xi =  \eta =  1\otimes e_1 \in \mathbb{C} \otimes \mathbb{C}^2$, then $W_{\xi}\eta(t,y)= 0.$
 Thus, $\{ (s,u)\in \mathbb{T}\times D_{3}: W_{\xi}\eta (s,u)\neq 0\} \subseteq \mathbb{T} \times D^{3}/{\{y\}}$ which implies that
 \begin{align*}
\mu_{G}\{ (s,u)\in \mathbb{T}\times D_{3}: W_{\xi}\eta(s,u)\neq 0\} \leq \mu_{\mathbb{T}}(\mathbb{T})\frac{\#(D^{3}/{\{y\}})}{\#(D_3)} < 1
\end{align*} where $\#(D_{3})$ is the cardinality of $D_3.$ 
 \end{enumerate}

\begin{enumerate}
\item[(i)] Using the data given in \cite{bans;15}, one may write the explicit form of the Heisenberg type inequality when  $A$ is a locally compact abelian group with non-compact identity component  or $n$-dimensional nilpotent Lie group or of the form $K\ltimes \mathbb{R},$ where $K$ is compact subgroup of  group of automorphism of $\mathbb{R}$.

\item[(ii)] As a particular case of above results, one can obtain results for abstract shearlet transform (see \cite{kam:15}) by taking $B= H\ltimes_{\lambda}K$, where $H$ and K are locally compact groups and $\lambda:H\to $ Aut$(K)$ is a homomorphism.
\end{enumerate}

