\begin{proof}
Let $P_R :L^2(G) \to L^2(G) $ be the orthogonal projection from $L^2(G)$ to the closed subspace $W_{\psi}(L^2(A))$ and $P_M :L^2(G) \to L^2(G)$ be the orthogonal projection from $L^2(G)$ to the closed subspace of functions with support contained in $M.$ Now, 
\begin{align}\label{conc}
\| W_{\psi}f - \chi_{M}\cdot W_{\psi}f\| &= \| W_{\psi}f- P_MP_R(W_{\psi}f)\| \nonumber \\ \nonumber
& \geq \|W_{\psi}f\| - \|P_MP_R\|\ \|W_{\psi}f\|\\
&= (1-\|P_MP_R\|)\ \sqrt{C_{\psi}}\ \|f\|.
\end{align}  
Now $P_R$ being a projection on a reproducing kernel Hilbert space can be represented by
\begin{align*}
P_RF(b,a) = \langle F(b^{'},a^{'}), k((b^{'},a^{'}), (b,a)) \rangle, 
\end{align*}
where $F \in L^2(G)$ and $k(.,.)$ is the reproducing kernel. Thus, for every $F\in L^2(G),$ we have
\begin{align*}
P_MP_RF(b,a) = 
\int_{G} \chi_{M}(b,a)k((b^{'},a^{'}), (b,a))F(b^{'},a^{'})d\mu(b^{'},a^{'}).
\end{align*} 
 From \cite{hal;78}, the operator norm $\|P_MP_R\|$  is given by
\begin{flalign*}
\| P_MP_R\|^{2} &= \int_{G}\int_{G}|\chi_{M}(b,a)\ k((b^{'},a^{'}),(b,a))|^2\ d\mu(b,a)\ d\mu(b^{'},a^{'})&\\
&=\int_{G}\int_{G}|\chi_{M}(b,a)\frac{1}{C_{\psi}}\langle \psi_{ba}, \psi_{b^{'}a^{'}}\rangle |^2\ d\mu(b,a)\ d\mu(b^{'},a^{'})&\\
&=\frac{1}{C_{\psi}^2}\int_{M} \int_{G}|W_{\psi}\psi_{ba}(b^{'},a^{'})|^2\ d\mu(b^{'},a^{'})\ d\mu(b,a)&\\
&=\frac{1}{C_{\psi}}\int_{M}\|\psi_{ba}\|^2\ d\mu(b,a)&\\
&= \frac{1}{C_{\psi}}\|\psi\|^{2}\ \mu(M).
\end{flalign*}
On substituting the value $\|P_MP_R\|$ into (\ref{conc}), we get the desired inequality.
\end{proof}

\noindent Next, we prove an analogue of Heisenberg type inequality for wavelet transform.

\begin{proof}
For almost all $b\in B$, using Heisenberg inequality for Fourier transform on $L\times \mathbb{R}$ (see \cite{bans;15}), we have
\begin{align*}
